import template from './config.html.twig';
import {
    philosophyContentLanguageMixin,
    resolvePhilosophyContent,
} from '../../../../../service/philosophy-content.js';

const { Mixin } = Shopware;

/** Übersetzbare Rich-Text-Konfiguration auf Shopwares CMS-Element-Mixin. */
export default {
    template,
    compatConfig: Shopware.compatConfig,
    emits: ['element-update'],
    mixins: [Mixin.getByName('cms-element'), philosophyContentLanguageMixin],

    computed: {
        resolvedContent() {
            return resolvePhilosophyContent(this.element?.config?.content?.value, this.contentLocale);
        },
    },

    created() {
        this.initElementConfig('mgd-ai-philosophy');
    },

    methods: {
        onInput(content) {
            this.element.config.content.value = typeof content === 'string' ? content : '';
            this.$emit('element-update', this.element);
        },
    },
};
